import math

logits = {'Paris': 4.0, 'Lyon': 2.0, 'London': 1.0}
for T in (0.5, 1.0, 2.0):
    exps = {t: math.exp(z / T) for t, z in logits.items()}
    total = sum(exps.values())
    print(T, {t: round(e / total, 3) for t, e in exps.items()})

