import math

T, k = input().split()
T, k = float(T), int(k)
n = int(input())
cands = []
for _ in range(n):
    tok, logit = input().split()
    cands.append((tok, float(logit)))

cands.sort(key=lambda c: (-c[1], c[0]))
if k > 0:
    cands = cands[:k]

if T == 0:
    probs = {tok: (1.0 if i == 0 else 0.0) for i, (tok, _) in enumerate(cands)}
else:
    top = cands[0][1]
    exps = {tok: math.exp((z - top) / T) for tok, z in cands}
    total = sum(exps.values())
    probs = {tok: e / total for tok, e in exps.items()}

for tok, p in sorted(probs.items(), key=lambda item: (-item[1], item[0])):
    print(f'{tok} {p:.3f}')
print(f'greedy={cands[0][0]}')
